# The link and the far side misbehave. The script must find out what is live.
remote_mode() {
    local mode="$1"
    shift
    RC=0
    OUT="$(env -u PACKS_DEST -u PACKS_BACKUP_DIR SHIM_MODE="${mode}" SHIM_DIR="${TMP}/shim" HOME="${TMP}/home" \
